<?php
declare(strict_types=1);
$root=dirname(__DIR__);$dsn=(string)getenv('DB_DSN');$dbUser=(string)getenv('DB_USER');$dbPass=(string)getenv('DB_PASS');if($dsn==='')throw new RuntimeException('DB_DSN is required.');
$pdo=new PDO($dsn,$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
foreach(['installer','storage','jobs','concurrency','functions','subscriptions','account-admin','account-membership','shell','access','notifications','rate-limit','ai','ai-access','source-integrity','annotation-intelligence','research-workspace','research-knowledge','research-intelligence','research-reports','conversations','agent-actions','agent-chat','cognitive-feed','research-entities','proactive-intelligence','research-automation','research-agent-workspace','research-agents','research-tasks','research-programs','research-missions','research-accounts','sponsored-research-campaigns','sponsored-research-participation','data-attribution','data-datasets','sponsored-research-submissions','sponsored-research-reviews','sponsored-research-finance','sponsored-research-knowledge','sponsored-research-datasets'] as $lib)require_once $root.'/app/'.$lib.'.php';
function p80s8(bool $ok,string $m):void{if(!$ok)throw new RuntimeException('FAIL: '.$m);echo "PASS: $m\n";}
$run='p80s8'.substr(bin2hex(random_bytes(5)),0,10);$pub=fn(string $p)=>$p.'-'.$run.'-'.substr(bin2hex(random_bytes(3)),0,6);
$make=function(string $name,string $role='user')use($pdo,$run,$pub):array{$u=substr(strtolower($name).'_'.$run,0,48);$pdo->prepare("INSERT INTO users(public_id,username,display_name,email,email_verified_at,status,role,plan_tier,live_presence_mode) VALUES(?,?,?,?,NOW(),'active',?,'pro','cloaked')")->execute([$pub('u'),$u,$name,$u.'@example.test',$role]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT IGNORE INTO user_preferences(user_id) VALUES(?)')->execute([$id]);$q=$pdo->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);return $q->fetch();};
$admin=$make('DatasetAdmin','admin');$sponsor=$make('DatasetSponsor');$researcher=$make('DatasetResearcher');
$pkg=(int)$pdo->query("SELECT id FROM subscription_packages WHERE slug='basic-user' LIMIT 1")->fetchColumn();
$pdo->prepare("INSERT INTO accounts(public_id,account_type,name,owner_user_id,personal_user_id,package_id,subscription_status,period_start,period_end,status) VALUES(?,'personal',?,?,?,?, 'active',CURRENT_DATE,DATE_ADD(CURRENT_DATE,INTERVAL 1 MONTH),'active')")->execute([$pub('acct'),'Dataset Sponsor Account',(int)$sponsor['id'],(int)$sponsor['id'],$pkg]);$accountId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO account_members(account_id,user_id,account_role) VALUES(?,?,'owner')")->execute([$accountId,(int)$sponsor['id']]);$q=$pdo->prepare('SELECT public_id FROM accounts WHERE id=?');$q->execute([$accountId]);$accountPublic=(string)$q->fetchColumn();
sponsor_account_apply($pdo,$sponsor,['organization_name'=>'Dataset Sponsor']);research_account_admin_decide($pdo,$admin,(int)$sponsor['id'],'sponsor_account','approved','Approved sponsor.','organization');
research_account_apply($pdo,$researcher,['specialties'=>'research','languages'=>'English']);research_account_admin_decide($pdo,$admin,(int)$researcher['id'],'research_account','approved','Approved researcher.','identity');
data_contributor_preferences_update($pdo,$researcher,['allow_shared_retrieval'=>1,'allow_evaluation'=>1,'allow_training'=>1,'allow_commercial_training'=>1,'attribution_required'=>1]);

$campaign=sponsored_research_campaign_create($pdo,$sponsor,['account_id'=>$accountPublic,'title'=>'Dataset Lineage Campaign','brief'=>'Build governed datasets from accepted research.','objective'=>'Validate consent and downstream lineage.','questions'=>['What does the evidence support?'],'access_mode'=>'public','budget'=>'500.00','eligibility'=>['min_verification'=>'identity'],'disclosures'=>['sponsorship_disclosure_required'=>false,'conflict_disclosure_required'=>false,'nda_required'=>false],'submission_deadline'=>'2030-12-31 23:59:00']);
$campaign=sponsored_research_campaign_set_status($pdo,$sponsor,(string)$campaign['public_id'],'open');sponsored_research_campaign_terms_publish($pdo,$sponsor,(string)$campaign['public_id'],'Participation does not grant dataset, evaluation, or training rights.','Dataset consent terms.');sponsored_research_campaign_join($pdo,$researcher,(string)$campaign['public_id'],['accept_terms'=>true]);
sponsored_research_finance_record_funding($pdo,$admin,(string)$campaign['public_id'],50000,'manual_admin','dataset-funding-'.$run);

$sourcePublic=$pub('source');$url='https://'.$run.'.example.test/evidence';$pdo->prepare("INSERT INTO sources(public_id,source_type,canonical_url,canonical_url_hash,domain,title,status) VALUES(?,'article',?,?,?,?, 'current')")->execute([$sourcePublic,$url,hash('sha256',$url),$run.'.example.test','Dataset source']);$sourceId=(int)$pdo->lastInsertId();
$text='Dataset evidence '.$run;$pdo->prepare('INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash,target_content_hash) VALUES(?,1,?,?,?,?,?)')->execute([$sourceId,$url,'Dataset source',$text,hash('sha256',$text),hash('sha256','target '.$run)]);$sv=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE sources SET current_version_id=? WHERE id=?')->execute([$sv,$sourceId]);
data_source_rights_set($pdo,$admin,$sourcePublic,['rights_class'=>'licensed','retrieval_allowed'=>1,'excerpt_storage_allowed'=>1,'model_context_allowed'=>1,'training_allowed'=>1,'commercial_training_allowed'=>0,'license_code'=>'DATASET-LICENSE','rights_holder'=>'Publisher']);
$pdo->prepare("INSERT INTO captures(public_id,source_id,source_version_id,user_id,capture_type,selected_text) VALUES(?,?,?,?, 'text',?)")->execute([$pub('cap'),$sourceId,$sv,(int)$researcher['id'],'Selected dataset evidence']);$cap=(int)$pdo->lastInsertId();
$ann=$pub('ann');$pdo->prepare("INSERT INTO annotations(public_id,user_id,source_id,source_version_id,capture_id,text_commentary,visibility,status) VALUES(?,?,?,?,?,?,'private','draft')")->execute([$ann,(int)$researcher['id'],$sourceId,$sv,$cap,'Dataset analysis '.$run]);
$draft=sponsored_research_submission_draft($pdo,$researcher,(string)$campaign['public_id'],['title'=>'Dataset submission','summary'=>'Accepted dataset candidate.','methodology'=>'Source review.','limitations'=>'Test scope.']);
$sub=sponsored_research_submission_submit($pdo,$researcher,(string)$draft['public_id'],[['type'=>'annotation','public_id'=>$ann],['type'=>'source','public_id'=>$sourcePublic]]);
sponsored_research_compensation_reserve($pdo,$sponsor,(string)$sub['public_id'],20000);$case=sponsored_research_review_open($pdo,$sponsor,(string)$sub['public_id'],[]);sponsored_research_review_decide($pdo,$sponsor,(string)$case['public_id'],'accepted','Accepted for Knowledge and potential dataset use.');
$kb=sponsored_research_knowledge_base_create($pdo,$sponsor,(string)$campaign['public_id'],['name'=>'Dataset KB']);
$assets=sponsored_research_knowledge_promotable_assets($pdo,$sponsor,(string)$campaign['public_id']);$asset=null;foreach($assets as $x)if($x['asset_public_id']===$ann)$asset=$x;p80s8($asset!==null,'Accepted annotation is available for explicit Knowledge promotion.');
$item=sponsored_research_knowledge_promote($pdo,$sponsor,(string)$kb['public_id'],(string)$asset['public_id']);$release=sponsored_research_knowledge_release_create($pdo,$sponsor,(string)$kb['public_id'],'Dataset source release.');

$elig=data_training_eligibility($pdo,'sponsored_knowledge_item',(string)$item['public_id']);p80s8($elig['training']===false&&$elig['reason']==='separate_sponsored_knowledge_consent_required','Global contributor training preferences do not substitute for explicit Sponsored Knowledge consent.');
$blocked=false;try{sponsored_research_dataset_assemble($pdo,$admin,(string)$release['public_id'],'training','Blocked Training Dataset');}catch(RuntimeException $e){$blocked=str_contains($e->getMessage(),'explicit consent');}p80s8($blocked,'Dataset assembly fails closed until every Knowledge item has purpose-specific consent.');

$grant=data_usage_grant_set($pdo,$researcher,'sponsored_knowledge_item',(string)$item['public_id'],['shared_retrieval_allowed'=>1,'evaluation_allowed'=>1,'training_allowed'=>1,'commercial_training_allowed'=>0,'attribution_required'=>1,'license_code'=>'SPONSORED-TRAINING']);
p80s8((int)$grant['training_allowed']===1&&(int)$grant['commercial_training_allowed']===0,'Researcher grants training separately without granting commercial training.');
$commercialBlocked=false;try{sponsored_research_dataset_assemble($pdo,$admin,(string)$release['public_id'],'commercial_training','Commercial Dataset');}catch(RuntimeException $e){$commercialBlocked=true;}p80s8($commercialBlocked,'Commercial training remains blocked without both contributor and Source commercial-training permission.');

$build=sponsored_research_dataset_assemble($pdo,$admin,(string)$release['public_id'],'training','Sponsored Training Dataset '.$run);
p80s8($build['status']==='frozen'&&$build['dataset_status']==='frozen'&&$build['purpose']==='training','Admin Dataset authority assembles and freezes a canonical training Dataset version.');
$dataset=data_dataset_get($pdo,(string)$build['dataset_public_id']);p80s8($dataset!==null&&(int)$dataset['item_count']===1&&$dataset['purpose']==='training','Canonical Dataset Registry contains the exact eligible Sponsored Knowledge item.');
$status=sponsored_research_dataset_current_use_status($pdo,(string)$build['public_id']);p80s8($status['usable']===true&&$status['consent_current']===true,'Frozen Sponsored dataset is current only while release, consent, rights, and Dataset integrity all validate.');

$q=$pdo->prepare("SELECT COUNT(*) FROM data_provenance_edges WHERE from_type='sponsored_knowledge_release' AND from_public_id=? AND relationship='assembled_into' AND to_type='dataset' AND to_public_id=?");$q->execute([(string)$release['public_id'],(string)$dataset['public_id']]);p80s8((int)$q->fetchColumn()===1,'Knowledge release → Dataset provenance edge is recorded.');
$q=$pdo->prepare("SELECT COUNT(*) FROM data_provenance_edges WHERE from_type='sponsored_knowledge_item' AND from_public_id=? AND relationship='included_in_dataset' AND to_type='dataset' AND to_public_id=?");$q->execute([(string)$item['public_id'],(string)$dataset['public_id']]);p80s8((int)$q->fetchColumn()===1,'Contributor Knowledge item → Dataset provenance edge survives assembly.');

data_usage_grant_revoke($pdo,$researcher,'sponsored_knowledge_item',(string)$item['public_id']);$status=sponsored_research_dataset_current_use_status($pdo,(string)$build['public_id']);p80s8($status['usable']===false,'Contributor consent revocation blocks future use of the frozen Dataset without deleting it.');
$still=data_dataset_get($pdo,(string)$dataset['public_id']);p80s8($still['status']==='frozen'&&$still['manifest_hash']===$dataset['manifest_hash'],'Consent revocation preserves the immutable historical Dataset manifest.');

data_usage_grant_set($pdo,$researcher,'sponsored_knowledge_item',(string)$item['public_id'],['shared_retrieval_allowed'=>1,'evaluation_allowed'=>1,'training_allowed'=>1,'commercial_training_allowed'=>0,'attribution_required'=>1,'license_code'=>'SPONSORED-TRAINING-V2']);
$status=sponsored_research_dataset_current_use_status($pdo,(string)$build['public_id']);p80s8($status['usable']===false&&$status['consent_current']===false,'A later re-grant does not silently rewrite the frozen Dataset consent snapshot; a new Dataset version is required.');

data_source_rights_set($pdo,$admin,$sourcePublic,['rights_class'=>'licensed','retrieval_allowed'=>1,'excerpt_storage_allowed'=>1,'model_context_allowed'=>1,'training_allowed'=>0,'commercial_training_allowed'=>0,'license_code'=>'DATASET-LICENSE','rights_holder'=>'Publisher']);
$elig2=data_training_eligibility($pdo,'sponsored_knowledge_item',(string)$item['public_id']);p80s8($elig2['training']===false,'Source training-rights revocation propagates through Sponsored Knowledge eligibility.');

echo "Phase 80 Section 8 Dataset Integration, Training Consent & Downstream Lineage database journey passed.\n";
